from candidate import triangle_area
import pytest
from unittest.mock import patch

@pytest.fixture
def valid_inputs():
    return (5, 3), (2, 4), (7, 2), (0, 5)

def test_triangle_area_with_positive_values(valid_inputs):
    for base, height in valid_inputs:
        with patch('builtins.print', new=pytest.mock.MagicMock()):
            result = triangle_area(base, height)
            expected = base * height / 2.0
            assert result == expected

def test_triangle_area_with_zero():
    assert triangle_area(0, 5) == 0

def test_triangle_area_with_negative():
    with pytest.raises(ValueError):
        triangle_area(-5, 3)

def test_triangle_area_with_non_numbers():
    with pytest.raises(TypeError):
        triangle_area('a', 3)

def test_triangle_area_with_floats():
    assert triangle_area(2.5, 4.2) == 5.3

def test_triangle_area_with_large_numbers():
    with pytest.raises(OverflowError):
        triangle_area(1e308, 1)
